// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {BaseEscalationManager} from "../src/BaseEscalationManager.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    BaseEscalationManager c;

    function setUp() public {
        c = new BaseEscalationManager();
    }

    function _test_requestPrice_reverts(bytes32 identifier, uint256 time, bytes memory ancillaryData) internal {
        bool reverted = false;
        try c.requestPrice(identifier, time, ancillaryData) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted);
    }

    function testFuzz_test_requestPrice_reverts(bytes32 identifier, uint256 time, bytes memory ancillaryData) public {
        _test_requestPrice_reverts(identifier, time, ancillaryData);
    }
}
